export function monsterArt(id, evolved = false) {
  // Unillustrated catalog entries get a neutral undiscovered silhouette,
  // never another creature's artwork. Future entries remain data-driven.
  const shape = faces[id] || `<path d="M40 104Q23 75 45 56Q55 31 90 31Q121 23 141 56Q157 80 140 111Q123 142 90 141Q52 142 40 104Z" fill="#d9e0d7" stroke="#859587" stroke-width="5"/><text x="90" y="105" text-anchor="middle" font-family="sans-serif" font-size="53" font-weight="800" fill="#859587">?</text>`;
  return `<svg viewBox="0 0 180 164" class="monster-svg ${evolved ? 'monster-evolved' : ''}" role="img" aria-label="モンスターのイラスト" xmlns="http://www.w3.org/2000/svg">${evolved ? '<path d="M35 37L23 18M144 38L157 20M91 16V3" stroke="#f2b64b" stroke-width="6" stroke-linecap="round"/>' : ''}${shape}</svg>`;
}
